"// Declare Arguments
const position = arguments[0].clamp(0, 10);

// Declare Variables
const bufferX = 200;
const width = Graphics.width - (bufferX * 2);

// Calculate X Position
let x = Math.round(position * width / 10) + bufferX;
x = x.clamp(bufferX, Graphics.width - bufferX);

// Return X Value
return x;"

