const position = arguments[0].clamp(0, 10);

// Declare Variables
const stagger = 0;
const difference = 5 - Math.abs(5 - position);
let y = Graphics.height;

// Calculate Y Position
y = Graphics.height + Math.round(difference * stagger) + 5;

// Return Y Value
return y;"

